# area: self_classmethods
# hypothesis: Methods annotated to return Self in a fluent builder keep the subclass type after chaining, so a checker should type each chained call on a HtmlBuilder as HtmlBuilder rather than Builder.
from typing import Self, reveal_type


class Builder:
    def __init__(self) -> None:
        self.parts: list[str] = []

    def add(self, part: str) -> Self:
        self.parts.append(part)
        return self

    def build(self) -> str:
        return '-'.join(self.parts)


class HtmlBuilder(Builder):
    def tag(self, name: str) -> Self:
        return self.add(f'<{name}>')

    @classmethod
    def start(cls) -> Self:
        return cls().add('root')


b = HtmlBuilder.start().tag('p').add('text')
reveal_type(b)
print(b.build())
print(type(Builder().add('x').add('y')).__name__)
